</div></div>
<script>document.getElementById('sideBtn')?.addEventListener('click',()=>{const s=document.getElementById('sidebar'); if(!s)return; s.classList.toggle('hidden'); s.classList.toggle('open')});(function(){const w=document.getElementById('userDropWrap'),b=document.getElementById('userBtn'),d=document.getElementById('userDrop');if(!w||!b||!d)return;b.addEventListener('click',e=>{e.stopPropagation();d.classList.toggle('hidden')});document.addEventListener('click',e=>{if(!w.contains(e.target))d.classList.add('hidden')});document.addEventListener('keydown',e=>{if(e.key==='Escape')d.classList.add('hidden')})})();</script>
